const input = $input.first().json;
const query = input.query || {};
const { estado, limit = 50, offset = 0 } = query;

const allowedEstados = ['PENDIENTE_VERIFICACION', 'VERIFICADO', 'RECHAZADO', 'DEVUELTO', 'PENDIENTE_PAGO'];
const estadoFilter = estado && allowedEstados.includes(estado) ? `p.estado = '${estado}'` : `p.estado = 'PENDIENTE_VERIFICACION'`;

const queryList = `SELECT
  p.id, p.alumno_id, p.horario_id, p.tipo, p.canal, p.monto, p.moneda, p.periodo,
  p.estado, p.comprobante_url, p.comprobante_fecha, p.comprobante_monto,
  p.verificado_por, p.verificado_at, p.notas_verificacion, p.created_at,
  a.nombre AS alumno_nombre, a.whatsapp AS alumno_whatsapp, a.email AS alumno_email,
  h.nombre AS horario_nombre, h.dia_semana, h.hora_inicio, h.hora_fin
FROM pagos p
LEFT JOIN alumnos a ON a.id = p.alumno_id
LEFT JOIN horarios h ON h.id = p.horario_id
WHERE ${estadoFilter}
ORDER BY p.created_at DESC
LIMIT ${parseInt(limit)} OFFSET ${parseInt(offset)};`;

const queryCount = `SELECT COUNT(*) as total FROM pagos p WHERE ${estadoFilter};`;

return [{ json: { queryList, queryCount, limit, offset } }];

const items = $('Select Pagos').all().map(row => row.json).filter(row => row && Object.keys(row).length > 0);
const totalData = $('Count Total').first().json;
const total = totalData.total;
const limit = $input.first().json.limit;
const offset = $input.first().json.offset;

return [{
  json: { items, total, limit, offset }
}];
